"""Builds the small sample workbooks ui8.js imports when the real review workbooks are not given
(LIB_XLSX / JD_XLSX unset). Same sheets and columns as the team's review files, read by
parseLibraryBook / parseJdBook in src/Index.html.

    python3 tests/fixtures/make_jd_books.py      → tests/fixtures/jd-library.xlsx, tests/fixtures/jd-sample.xlsx
"""
import os
from openpyxl import Workbook

HERE = os.path.dirname(os.path.abspath(__file__))


def book(sheets, path):
    wb = Workbook()
    wb.remove(wb.active)
    for name, rows in sheets:
        ws = wb.create_sheet(name)
        for r in rows:
            ws.append(r)
    wb.save(path)


# ---- competency library: 4 competencies (one marked for deletion), questions, one practical test
comps = [
    ['C01', 'أساسية', 'التركيز على العميل', 'Customer focus', 'يفهم احتياج العميل ويخدمه', '', 'مقابلة', ''],
    ['C02', 'أساسية', 'العمل الجماعي', 'Teamwork', 'يتعاون مع زملائه لتحقيق الهدف', '', 'مقابلة', ''],
    ['S01', 'فنية — مبيعات المعارض', 'عرض المنتج', 'Product presentation', 'يعرض المنتج بثقة ويرد على الاعتراضات', '', 'مقابلة · اختبار عملي', ''],
    ['S99', 'فنية — مبيعات المعارض', 'كفاءة قديمة', 'Old', 'تتشال', '', 'مقابلة', 'يُحذف'],
]
levels = [[c[0], c[2], 'أساسي', 'متوسط', 'متقدم', 'خبير'] for c in comps]
required = [[c[0], c[2], ''] + [1, 2, 2, 3, 3, 4, 4] for c in comps]
questions = [
    ['C01', 'التركيز على العميل', 1, 'احكيلي عن عميل صعب وإزاي اتعاملت معاه', 'مثال محدد ونتيجة', 'كلام عام', 'المكتبة', ''],
    ['C02', 'العمل الجماعي', 1, 'احكيلي عن مرة ساعدت فيها زميل', 'دور واضح', 'مفيش مثال', 'المكتبة', ''],
    ['S01', 'عرض المنتج', 1, 'اعرض علينا المنتج ده كأني عميل', 'ثقة وترتيب', 'تردد', 'المكتبة', ''],
]
tests = [['S01', 'عرض المنتج', 'عرض منتج لعميل', 'المرشح يعرض قطعة أثاث على مقيّم', '15 دقيقة', '3 من 5', 'مدير المعرض', '']]
book([
    ('الكفاءات', [['الكود', 'المجموعة', 'الكفاءة', 'English', 'التعريف', '', 'طريقة القياس', 'رأي الفريق']] + comps),
    ('مستويات الإتقان', [['الكود', 'الكفاءة', '1', '2', '3', '4']] + levels),
    ('المستوى المطلوب', [['الكود', 'الكفاءة', '', 'JL1', 'JL2', 'JL3', 'JL4', 'JL5', 'JL6', 'JL7']] + required),
    ('أسئلة المقابلة', [['الكود', 'الكفاءة', 'م', 'السؤال', 'إجابة قوية', 'إجابة ضعيفة', 'المصدر', 'رأي الفريق']] + questions),
    ('الاختبارات العملية', [['الكود', 'الكفاءة', 'الاختبار', 'الطريقة', 'المدة', 'النجاح', 'المسؤول', 'رأي الفريق']] + tests),
], os.path.join(HERE, 'jd-library.xlsx'))

# ---- job descriptions: 6 jobs; SLS-009 has 8 responsibilities, one marked for deletion → 7
jobs = [
    ['SLS-009', 'أخصائي مبيعات معرض', 'لا يوجد', 'JL3 — تخصصي', 'بيع منتجات الشركة في المعرض وخدمة العملاء'],
    ['SLS-010', 'مشرف معرض', '3 أخصائيين', 'JL4 — إشرافي', 'الإشراف على فريق المعرض وتحقيق المستهدف'],
    ['PRD-006', 'فني تشغيل', 'لا يوجد', 'JL2 — فني', 'تشغيل خط الإنتاج حسب التعليمات'],
    ['PRD-007', 'مشرف إنتاج', '10 فنيين', 'JL4 — إشرافي', 'الإشراف على الوردية وتحقيق الإنتاج المطلوب'],
    ['FIN-001', 'محاسب', 'لا يوجد', 'JL3 — تخصصي', 'تسجيل القيود ومراجعة المستندات'],
    ['HRM-002', 'أخصائي توظيف', 'لا يوجد', 'JL3 — تخصصي', 'استقطاب واختيار المرشحين'],
]
head = ['كود الوظيفة', 'الوظيفة', 'المرؤوسون', 'مستوى الوظيفة', 'الغرض من الوظيفة', 'حجم الوظيفة', 'علاقات داخلية', 'علاقات خارجية',
        'ظروف العمل', 'المؤهل المطلوب', 'الخبرة المطلوبة', 'الفرق بين الأقسام', 'الحرفة', 'الاختبار العملي', 'تأكيد مطلوب']
main = [j + ['', 'الأقسام المعنية', 'العملاء', 'مكتب / موقع', 'مؤهل عالي', 'سنتين', '', '', '', ''] for j in jobs]
resp = []
for j in jobs:
    n = 8 if j[0] == 'SLS-009' else 4
    for i in range(1, n + 1):
        resp.append([j[0], j[1], i, 'مسؤولية رقم ' + str(i) + ' — ' + j[1], 'يُحذف' if (j[0] == 'SLS-009' and i == 8) else ''])
kpis = [[j[0], j[1], 'تحقيق المستهدف', 'المحقق ÷ المستهدف', 'شهري', 100, 'موزون'] for j in jobs]     # v0.42.2: «الوزن» and «النوع» by name, as the job-profile file v0.11
auth = [[j[0], j[1], 'اعتماد المستندات في حدود عمله', 'ينفذ'] for j in jobs]
jcomps = []
for j in jobs:
    for c in (['C01', 'C02', 'S01'] if j[0].startswith('SLS') else ['C01', 'C02']):
        jcomps.append([j[0], j[1], c, '', '', 'المستوى 3', 'مقابلة'])
book([
    ('الأوصاف', [head] + main),
    ('المسؤوليات', [['كود الوظيفة', 'الوظيفة', 'م', 'المسؤولية', 'رأي الفريق']] + resp),
    ('مؤشرات الأداء', [['كود الوظيفة', 'الوظيفة', 'المؤشر', 'طريقة الحساب', 'الدورية', 'الوزن', 'النوع']] + kpis),
    ('الصلاحيات', [['كود الوظيفة', 'الوظيفة', 'الصلاحية', 'المستوى']] + auth),
    ('الكفاءات', [['كود الوظيفة', 'الوظيفة', 'الكود', '', '', 'المستوى', 'طريقة القياس']] + jcomps),
], os.path.join(HERE, 'jd-sample.xlsx'))
print('jd-library.xlsx, jd-sample.xlsx written; jobs:', len(jobs))
